{"content":"#!/usr/bin/env python3
"""Minesweeper safest-move solver (16x16). Reads /app/board.txt, writes /app/safe_move.txt."""
import sys
import random
from collections import defaultdict

BOARD_PATH = "/app/board.txt"
OUT_PATH = "/app/safe_move.txt"
N = 16
TOTAL_MINES = 40  # standard 16x16 intermediate count, used only for ranking isolated cells
EXACT_LIMIT = 25  # max vars per component for exact enumeration
SOLUTION_CAP = 200000  # abort exact if solutions exceed this


def write_move(r, c):
    with open(OUT_PATH, "w") as f:
        f.write(f"{r},{c}")


def fail():
    write_move(-1, -1)


def parse_board():
    try:
        with open(BOARD_PATH, "r") as f:
            raw_lines = f.read().strip().splitlines()
    except Exception:
        return None
    # remove empty lines
    lines = [ln.strip() for ln in raw_lines if ln.strip() != ""]
    if len(lines) != N:
        return None
    board = []
    for ln in lines:
        parts = ln.split()
        if len(parts) != N:
            return None
        row = []
        for p in parts:
            if p == ".":
                row.append(".")
            elif len(p) == 1 and p.isdigit() and 0 <= int(p) <= 8:
                row.append(p)
            else:
                return None
        board.append(row)
    return board


def neighbors(r, c, R, C):
    for rr in range(max(0, r - 1), min(R, r + 2)):
        for cc in range(max(0, c - 1), min(C, c + 2)):
            if rr == r and cc == c:
                continue
            yield rr, cc


def solve():
    board = parse_board()
    if board is None:
        fail()
        return
    R = len(board)
    C = len(board[0])
    hidden = [(r, c) for r in range(R) for c in range(C) if board[r][c] == "."]
    if not hidden:
        fail()
        return

    # Build constraints from numbered cells
    # constraint: (set of frontier positions, need)
    numbered = []
    for r in range(R):
        for c in range(C):
            v = board[r][c]
            if v != ".":
                numbered.append((r, c, int(v)))

    # hidden set for quick lookup
    hidden_set = set(hidden)

    constraints_raw = []  # list of (list_of_pos, need)
    for (r, c, v) in numbered:
        neigh_hidden = [(rr, cc) for (rr, cc) in neighbors(r, c, R, C) if (rr, cc) in hidden_set]
        need = v  # revealed neighbors are never mines; no flags in this format
        if need < 0 or need > len(neigh_hidden):
            fail()
            return
        if len(neigh_hidden) == 0:
            if need != 0:
                fail()
                return
            continue
        constraints_raw.append((neigh_hidden, need))

    # Frontier = hidden adjacent to some number
    frontier_set = set()
    for (cells, _) in constraints_raw:
        for p in cells:
            frontier_set.add(p)
    frontier = sorted(frontier_set)
    isolated = sorted(hidden_set - frontier_set)

    if not frontier:
        # No constraints touching hidden cells.
        # Either no numbers at all, or numbers fully surrounded by revealed.
        # All hidden symmetric -> pick first.
        r, c = hidden[0]
        write_move(r, c)
        return

    # Map frontier pos -> idx
    fidx = {p: i for i, p in enumerate(frontier)}
    # constraints as (set of idx, need)
    constraints = []
    for (cells, need) in constraints_raw:
        s = set(fidx[p] for p in cells)
        constraints.append([s, need])

    # --- Sound deductive propagation (safe/mine) with subset rule ---
    # known: dict idx -> 0 safe / 1 mine
    known = {}

    def propagate(constraints, known):
        """Iterative sound propagation. Returns (inconsistent:bool, newly_safe:set(idx), newly_mine:set(idx))."""
        # Work on mutable copies of constraint cell sets with known removed incrementally.
        # We'll loop until fixpoint.
        # To avoid mutating caller's sets, copy.
        cons = [[set(s), need] for (s, need) in constraints]
        # apply already known
        for idx, val in list(known.items()):
            for (s, need) in cons:
                if idx in s:
                    s.remove(idx)
                    if val == 1:
                        need -= 1
            # need stored in list; update
            for i in range(len(cons)):
                pass
        # fix need updates: we modified need variable above but need to write back
        # redo properly:
        cons = [[set(s), need] for (s, need) in constraints]
        for idx, val in known.items():
            for entry in cons:
                if idx in entry[0]:
                    entry[0].remove(idx)
                    if val == 1:
                        entry[1] -= 1
        changed = True
        while changed:
            changed = False
            # basic checks + single-constraint inference
            for entry in cons:
                s, need = entry[0], entry[1]
                if need < 0 or need > len(s):
                    return True, set(), set()
                if len(s) == 0:
                    continue
                if need == 0:
                    for idx in list(s):
                        if idx not in known:
                            known[idx] = 0
                            changed = True
                    # will be removed below
                elif need == len(s):
                    for idx in list(s):
                        if idx not in known:
                            known[idx] = 1
                            changed = True
            # remove known from constraints
            if changed:
                for idx, val in list(known.items()):
                    for entry in cons:
                        if idx in entry[0]:
                            entry[0].remove(idx)
                            if val == 1:
                                entry[1] -= 1
                # re-loop to check consistency before subset rule
                continue
            # subset rule
            # only consider non-empty constraints
            nonempty = [e for e in cons if len(e[0]) > 0]
            L = len(nonempty)
            found = False
            for i in range(L):
                si, ni = nonempty[i][0], nonempty[i][1]
                if len(si) == 0:
                    continue
                for j in range(L):
                    if i == j:
                        continue
                    sj, nj = nonempty[j][0], nonempty[j][1]
                    if len(sj) == 0:
                        continue
                    if si < sj:  # strict subset
                        diff = sj - si
                        ndiff = nj - ni
                        if ndiff < 0 or ndiff > len(diff):
                            return True, set(), set()
                        if ndiff == 0:
                            for idx in diff:
                                if idx not in known:
                                    known[idx] = 0
                                    found = True
                        elif ndiff == len(diff):
                            for idx in diff:
                                if idx not in known:
                                    known[idx] = 1
                                    found = True
                        if found:
                            break
                if found:
                    break
            if found:
                for idx, val in list(known.items()):
                    for entry in cons:
                        if idx in entry[0]:
                            entry[0].remove(idx)
                            if val == 1:
                                entry[1] -= 1
                changed = True
        # final consistency check
        for entry in cons:
            if entry[1] < 0 or entry[1] > len(entry[0]):
                return True, set(), set()
        return False, cons, known

    # run propagation
    known = {}
    inconsistent, cons_or_flag, known = propagate(constraints, known)
    # propagate returns (inconsistent, cons, known) on success; on inconsistency returns (True,...)
    if inconsistent is True and not isinstance(cons_or_flag, list):
        fail()
        return
    if inconsistent:
        fail()
        return
    cons = cons_or_flag  # filtered constraints with known removed (list of [set, need])

    # If any guaranteed safe, return one (smallest row,col for determinism)
    safe_idxs = [idx for idx, v in known.items() if v == 0]
    if safe_idxs:
        safe_positions = sorted([frontier[i] for i in safe_idxs])
        r, c = safe_positions[0]
        write_move(r, c)
        return

    # Remove known mines from candidate consideration; keep reduced constraints
    # cons already has known removed. Build remaining unknown vars.
    remaining_vars = set()
    for (s, need) in cons:
        remaining_vars.update(s)
    # known mines are excluded from picking
    mine_idxs = set(idx for idx, v in known.items() if v == 1)

    # Split remaining into connected components
    # Build adjacency var->constraints
    var_to_cons = defaultdict(list)
    for ci, (s, need) in enumerate(cons):
        for v in s:
            var_to_cons[v].append(ci)

    visited = set()
    components = []  # list of (var_list, constraint_indices)
    for v in remaining_vars:
        if v in visited:
            continue
        # BFS
        stack = [v]
        comp_vars = set()
        comp_cons = set()
        visited.add(v)
        while stack:
            cur = stack.pop()
            comp_vars.add(cur)
            for ci in var_to_cons.get(cur, []):
                comp_cons.add(ci)
                s, _ = cons[ci]
                for nb in s:
                    if nb not in visited:
                        visited.add(nb)
                        stack.append(nb)
        components.append((sorted(comp_vars), sorted(comp_cons)))

    # For each component, enumerate
    # Store per-component results: dict var_idx -> prob, expected_mines, min/max, solutions
    comp_results = []  # list of dicts
    any_inconsistency = False

    random.seed(0)

    for (cvars, ccis) in components:
        n = len(cvars)
        # local mapping global idx -> local 0..n-1
        g2l = {g: i for i, g in enumerate(cvars)}
        # local constraints: list of (list of local idx, need)
        lcons = []
        for ci in ccis:
            s, need = cons[ci]
            lst = [g2l[g] for g in s]
            lcons.append((lst, need))
        if n == 0:
            continue
        if n <= EXACT_LIMIT:
            # exact backtracking
            # order vars by degree desc
            deg = [0] * n
            for (lst, _) in lcons:
                for li in lst:
                    deg[li] += 1
            order = sorted(range(n), key=lambda i: (-deg[i], i))
            # reorder: pos_in_order -> var; we assign in order sequence
            # For fast checking, precompute constraint var lists as sets
            # assignment array local idx -> -1/0/1
            assign = [-1] * n
            mine_counts = [0] * n
            count_by_k = defaultdict(int)
            # per-cell per-k counts: list of dict k->count
